import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Retro — the postnorm family: log_softmax's wrapped-reduction gap closed","description":"","frontmatter":{},"headers":[],"relativePath":"graphopt/project/retros/handler-grammar-postnorm.md","filePath":"vendored/graphopt/project/retros/handler-grammar-postnorm.md"}`),a={name:`graphopt/project/retros/handler-grammar-postnorm.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="retro-—-the-postnorm-family-log-softmax-s-wrapped-reduction-gap-closed" tabindex="-1">Retro — the <code>postnorm</code> family: <code>log_softmax</code>&#39;s wrapped-reduction gap closed <a class="header-anchor" href="#retro-—-the-postnorm-family-log-softmax-s-wrapped-reduction-gap-closed" aria-label="Permalink to “Retro — the postnorm family: log_softmax&#39;s wrapped-reduction gap closed”">​</a></h1><p><strong>Date</strong>: 2026-10-17. <strong>Scope</strong>: <code>mlopt_discovery/handler_synth.py</code>, <code>lab/audit/grammar_probe.py</code>, <code>tests/test_discovery_handler_synth.py</code>.</p><p><strong>Depends on</strong>: <code>project/retros/grammar-gaps.md</code> (the residue this closes), ADR 0007 layer 2 (the handler grammar), plan 0025 §B (grammar extension by measured refusal, not taste).</p><h2 id="the-residue" tabindex="-1">The residue <a class="header-anchor" href="#the-residue" aria-label="Permalink to “The residue”">​</a></h2><p><code>grammar-gaps.md</code> named it: <em>&quot;<code>log_softmax</code> (a real invisible corpus op, 2 sites) — a normalization whose reduction result is wrapped in a unary (<code>log . sum . exp</code>) or a <code>logsumexp</code> reduction; the <code>norm</code> template covers a bare reduction operand only, and <code>logsumexp</code> has no torch binding.&quot;</em> A <code>norm</code> body computes <code>op(lhs, red(rhs, axis, keepdim))</code> — the reduction output is a bare operand of the outer op. <code>log_softmax(x) = x - log(sum(exp x))</code> needs the reduction <em>result</em> wrapped in <code>log</code>, so no <code>norm</code> body verifies — a grammar-coverage refusal (candidates proposed, none verify).</p><h2 id="the-extension" tabindex="-1">The extension <a class="header-anchor" href="#the-extension" aria-label="Permalink to “The extension”">​</a></h2><p><code>(&quot;postnorm&quot;, op, lhs, post, red_op, rhs, axis, keepdim)</code> — <code>op(lhs, post(red_op(rhs, axis, keepdim)))</code>, where <code>post</code> is a unary from the new <code>POST_UNARY</code> vocabulary. Deliberately minimal:</p><ul><li><code>POST_UNARY = (&quot;log&quot;,)</code> — only the measured wrap. Other wraps are a grammar extension, not a candidate.</li><li>The family is <strong>seed-only</strong>: <code>_canonical_postnorm_seeds</code> proposes <code>op(meta, post(red_op(ew, axis, keepdim)))</code> — a bare-meta lhs (the value being centered/scaled) over the shallow elementwise rhs vocabulary, <code>op</code>/<code>post</code>/<code>red_op</code>/<code>axis</code> over their banks. ~160 candidates for a 1-meta spec. No full column walk exists — a non-canonical <code>postnorm</code> body is a declared grammar gap, not hidden search.</li><li>Same shape gate as <code>norm</code> (proposed only when the spec&#39;s top op is in <code>NORM_OPS</code>); <code>_admitted_families</code> admits it for any non-empty meta set; <code>_GRAMMAR_VERSION</code> bumps to <code>handler-grammar-v2</code> (the vocabulary changed, so the provenance stamp must too — one existing pin updated).</li><li>Records round-trip unchanged: <code>body_to_data</code>/<code>handler_from_record</code> are generic over the descriptor tuple, and <code>provenance.family</code> reads <code>body[0]</code> = <code>&quot;postnorm&quot;</code>.</li></ul><h2 id="measured" tabindex="-1">Measured <a class="header-anchor" href="#measured" aria-label="Permalink to “Measured”">​</a></h2><ul><li><code>log-softmax</code> spec (<code>sub(X, log(sum(exp X, -1, keepdim)))</code>) — <strong>minted</strong> <code>(&quot;postnorm&quot;, &quot;sub&quot;, &quot;X&quot;, &quot;log&quot;, &quot;sum&quot;, (&quot;exp&quot;,&quot;X&quot;), -1, True)</code>; verified at the fp64 gate, and the descriptor agrees with <code>torch.nn.functional.log_softmax</code> to 1e-12 (pinned by test).</li><li><code>grammar_probe.py</code> battery gains the <code>&quot;log-softmax&quot;</code> spec so the census reports the family&#39;s reach.</li><li>The other grammar-gap residue — the <em>stabilized</em> (clamped) scan — stays open: it is a non-affine two-state recurrence, a semantics extension, not a vocabulary one (unchanged verdict).</li></ul><h2 id="gates" tabindex="-1">Gates <a class="header-anchor" href="#gates" aria-label="Permalink to “Gates”">​</a></h2><ul><li><code>pytest tests/test_discovery_handler_synth.py</code> — <strong>47 passed</strong> (4 new: <code>eval_body</code> on the descriptor, the <code>log_softmax</code> mint, the shape gate, the record round-trip).</li><li><code>ruff check</code> / <code>ruff format --check</code> on the touched files — clean.</li><li><code>ty check</code> — 0 errors.</li></ul>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};